"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[835],{34912:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"MeleeHandler","desc":"Category handler for melee combo weapons. On left-click it runs the shared\\n`resolveComboSwing` to pick the next combo step (buffering the click while\\nthe current hit is still in recovery), then predicts that step: plays its\\nswing sound + optional animation, runs the step hitbox for an instant\\nhitmarker (`Signals.WeaponLocalHit`), draws the debug box, fires\\n`Signals.WeaponComboChanged`, and sends\\n`Packets.ReqMeleeSwing` (with the Chrono render time for lag compensation) for the server to apply authoritative damage. Combo\\nstate is per-equipped-Tool (cleared on unequip), so it resets correctly on\\nrespawn/weapon-switch.","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/MeleeHandler.luau"}}')}}]);